'use client'
import { useState, useSyncExternalStore } from 'react'
import { supabase } from '../lib/supabase'
import { useRouter } from 'next/navigation'
import { avecSuite, lireSuite, sAbonnerAucunChangement } from '../lib/redirection'

export default function SignupPage() {
  const [nom, setNom] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const router = useRouter()
  // Page où revenir après l'inscription (ex. une invitation d'équipe)
  const suite = useSyncExternalStore(sAbonnerAucunChangement, lireSuite, () => null)

  const handleSignup = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    setLoading(true)
    
    const { error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: { nom_complet: nom }
      }
    })
    
    setLoading(false)
    
    if (error) {
      setError(error.message)
    } else {
      alert(suite?.startsWith('/invitation/')
        ? 'Inscription réussie ! Confirme ton email, puis connecte-toi pour rejoindre l’équipe.'
        : 'Inscription réussie ! Vérifie ton email.')
      router.push(avecSuite('/login', suite))
    }
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-900 to-black text-white flex items-center justify-center">
      <div className="bg-gray-800 p-8 rounded-lg shadow-lg w-full max-w-md">
        <h1 className="text-3xl font-bold text-center mb-8 text-blue-400">
          Créer un compte
        </h1>
        
        {suite?.startsWith('/invitation/') && (
          <div className="bg-blue-950 border border-blue-700 text-blue-100 p-3 rounded-lg mb-4 text-sm">
            👥 Créez votre compte avec l’adresse email qui a reçu l’invitation.
          </div>
        )}

        {error && (
          <div className="bg-red-500 text-white p-3 rounded-lg mb-4">
            {error}
          </div>
        )}
        
        <form className="space-y-6" onSubmit={handleSignup}>
          <div>
            <label className="block text-gray-300 mb-2">Nom complet</label>
            <input
              type="text"
              value={nom}
              onChange={(e) => setNom(e.target.value)}
              className="w-full px-4 py-3 bg-gray-700 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
              placeholder="Jean Dupont"
              required
            />
          </div>
          
          <div>
            <label className="block text-gray-300 mb-2">Email</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full px-4 py-3 bg-gray-700 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
              placeholder="ton@email.com"
              required
            />
          </div>
          
          <div>
            <label className="block text-gray-300 mb-2">Mot de passe</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-4 py-3 bg-gray-700 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
              placeholder="••••••••"
              required
            />
          </div>
          
          <button
            type="submit"
            disabled={loading}
            className="w-full bg-blue-600 text-white py-3 rounded-lg font-semibold hover:bg-blue-700 disabled:opacity-50"
          >
            {loading ? 'Inscription...' : "S'inscrire"}
          </button>
        </form>
        
        <p className="text-center text-gray-400 mt-6">
          Déjà un compte ?{' '}
          <a href={avecSuite('/login', suite)} className="text-blue-400 hover:underline">
            Se connecter
          </a>
        </p>
      </div>
    </div>
  )
}